use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut longest_prefix = String::new();
    let mut current_prefix = String::new();

    for item in input.as_array() {
        let mut current_item = item.as_str().unwrap();
        while !current_item.is_empty() && !current_item.starts_with(&current_prefix) {
            current_prefix.pop();
        }
        longest_prefix = current_prefix.clone();
    }

    longest_prefix
}
